localize tags:\n  pnpm exec nx extract-i18n shell","tree":{"sha":"9ff193f9e9e4b90443c25c5095225c02bfbe623f","url":"https://api.github.com/repos/Ouokki/angular-large-app-architecture/git/trees/9ff193f9e9e4b90443c25c5095225c02bfbe623f"},"url":"https://api.github.com/repos/Ouokki/angular-large-app-architecture/git/commits/dc4918cde97b2433f79bc6cc294e607b69aa42ba","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/56548633?v=4","events_url":"https://api.github.com/users/Ouokki/events{/privacy}","followers_url":"https://api.github.com/users/Ouokki/followers","following_url":"https://api.github.com/users/Ouokki/following{/other_user}","gists_url":"https://api.github.com/users/Ouokki/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Ouokki","id":56548633,"login":"Ouokki","node_id":"MDQ6VXNlcjU2NTQ4NjMz","organizations_url":"https://api.github.com/users/Ouokki/orgs","received_events_url":"https://api.github.com/users/Ouokki/received_events","repos_url":"https://api.github.com/users/Ouokki/repos","site_admin":false,"starred_url":"https://api.github.com/users/Ouokki/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Ouokki/subscriptions","type":"User","url":"https://api.github.com/users/Ouokki","user_view_type":"public"},"html_url":"https://github.com/Ouokki/angular-large-app-architecture/commit/dc4918cde97b2433f79bc6cc294e607b69aa42ba","node_id":"C_kwDOSbDot9oAKGRjNDkxOGNkZTk3YjI0MzNmNzliYzZjYzI5NGU2MDdiNjlhYTQyYmE","parents":[{"html_url":"https://github.com/Ouokki/angular-large-app-architecture/commit/bba173d37cdb3487a153911d6d2bd0edf70fb5ca","sha":"bba173d37cdb3487a153911d6d2bd0edf70fb5ca","url":"https://api.github.com/repos/Ouokki/angular-large-app-architecture/commits/bba173d37cdb3487a153911d6d2bd0edf70fb5ca"}],"sha":"dc4918cde97b2433f79bc6cc294e607b69aa42ba","url":"https://api.github.com/repos/Ouokki/angular-larg